#include <iostream>

int quadrat(int x) {      // Rückgabetyp + Parametertyp
    return x * x;
}

void begruesse(std::string name) {
    std::cout << "Hallo " << name << "!";
}

int main() {
    std::cout << quadrat(4);   // 16
    begruesse("Anna");
    return 0;
}

// Prototyp: int quadrat(int x);  -> Definition später

void beschreibe(std::string name, int alter,
                std::string stadt = "unbekannt") {
    std::cout << name << ", " << alter
              << ", aus " << stadt;
}

beschreibe("Anna", 25);            // Default genutzt
beschreibe("Ben", 30, "Bonn");

// Referenz statt Kopie:
